questions.solution:
type OrderLine = { sku: string; quantity: number };

function isOrderLine(value: unknown): value is OrderLine {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const input = value as Record<string, unknown>;
  return (
    typeof input.sku === "string" &&
    input.sku.length > 0 &&
    typeof input.quantity === "number" &&
    Number.isInteger(input.quantity) &&
    input.quantity >= 1
  );
}

for (const text of ['{"sku": "RICE-5", "quantity": 2}', '{"sku": "RICE-5", "quantity": "2"}', "[1, 2]", "null", '{"sku": "", "quantity": 1}']) {
  console.log(text, isOrderLine(JSON.parse(text)));
}

