function pickFields(input: Record<string, unknown>, allowed: readonly string[]): Record<string, unknown> {
  const output: Record<string, unknown> = {};
  for (const key of allowed) {
    if (Object.hasOwn(input, key)) output[key] = input[key];
  }
  return output;
}

const body = JSON.parse('{"name": "Ada Obi", "phone": "0803 555 0142", "role": "admin", "balanceKobo": 99999999}');
console.log(pickFields(body, ["name", "phone", "email"]));

