type Issue = { path: string; message: string };
type Result<T> = { ok: true; value: T } | { ok: false; issues: Issue[] };
interface Schema<T> {
  parse(value: unknown, path?: string): Result<T>;
}

function integer(min: number, max: number): Schema<number> {
  return {
    parse(value, path = "(root)") {
      if (typeof value !== "number" || !Number.isInteger(value)) {
        return { ok: false, issues: [{ path, message: "expected a whole number" }] };
      }
      if (value < min || value > max) {
        return { ok: false, issues: [{ path, message: `must be from ${min} to ${max}` }] };
      }
      return { ok: true, value };
    },
  };
}

const quantity = integer(1, 50);
for (const value of [2, 0, 2.5, "3", 51]) console.log(JSON.stringify(quantity.parse(value, "items[0].quantity")));

