questions.solution:
function validateItems(items: unknown): string[] {
  const issues: string[] = [];
  if (!Array.isArray(items)) return ["items: expected an array"];
  if (items.length === 0) return ["items: must have at least 1 item"];
  items.forEach((item: unknown, i) => {
    const path = `items[${i}]`;
    if (typeof item !== "object" || item === null) {
      issues.push(`${path}: expected an object`);
      return;
    }
    const line = item as Record<string, unknown>;
    if (typeof line.sku !== "string") issues.push(`${path}.sku: expected a string`);
    if (typeof line.quantity !== "number" || !Number.isInteger(line.quantity)) issues.push(`${path}.quantity: expected a whole number`);
    else if (line.quantity < 1) issues.push(`${path}.quantity: must be at least 1`);
  });
  return issues;
}

console.log(validateItems([{ sku: "RICE-5", quantity: 2 }, { sku: "EGG-30", quantity: 0 }, { quantity: 1 }]));
console.log(validateItems([]));
console.log(validateItems("RICE-5"));

